<script setup lang="ts">
import { NAlert, NButton, NCard, NEmpty, NInput, NSkeleton,NDrawer,NDrawerContent } from 'naive-ui';
import {useNarrowViewport} from '../../shared/ui/useNarrowViewport';
import PageHeader from '../../shared/ui/PageHeader.vue';
import InfoHint from '../../shared/ui/InfoHint.vue';
import EmployeeAvatar from '../../shared/ui/EmployeeAvatar.vue';
import type { Entity, Workspace } from '../../shared/api';
import type { ChatMode } from '../../phase2';
import ConversationTaskList from '../tasks/ConversationTaskList.vue';
import { useConversationSession } from './useConversationSession';
import { ref, nextTick } from 'vue';
import { composerAction } from './composer-keyboard';
const props = defineProps<{ entity: Entity; workspace: Workspace; initialConversationId?: string; initialMode?: ChatMode; embedded?:boolean }>();
const emit = defineEmits<{ (event: 'close' | 'sessionExpired' | 'editSettings'): void; (event: 'entityUpdated', entity: Entity): void; (event: 'conversationSelected' | 'openTasks', id: string): void }>();
const { base, continuationAllowed,readOnlyReason,canManageEntity, conversation, messages, text, error, notice, busy, turn, interrupting, loaded, generating, historicalReadOnly, send, interrupt, refresh, reopen } = useConversationSession(props, emit);
const composing=ref(false),taskView=ref(false),narrow=useNarrowViewport();
function onComposerKey(event:KeyboardEvent){
  const action=composerAction(event,composing.value);if(action==='none')return;
  event.preventDefault();if(busy.value||historicalReadOnly.value)return;
  if(action==='send'){if(text.value.trim())void send();return;}
  const target=event.target as HTMLTextAreaElement,start=target.selectionStart??text.value.length,end=target.selectionEnd??start;
  const value=text.value.slice(0,start)+'\n'+text.value.slice(end);if(value.length>8000)return;text.value=value;
  void nextTick(()=>target.setSelectionRange(start+1,start+1));
}
</script>
<template>
  <section class="entity-workspace">
    <PageHeader v-if="!embedded" class="workspace-heading" :title="entity.name"><template #leading><div class="chat-header-leading"><NButton aria-label="返回对话列表" :disabled="busy||interrupting" @click="emit('close')">← 返回</NButton><EmployeeAvatar :name="entity.name" :preset="entity.avatarPreset" :identity-key="entity.id" size="chat"/></div></template><NButton :disabled="busy || interrupting" @click="emit('editSettings')">{{ canManageEntity ? '员工设置' : '查看配置' }}</NButton></PageHeader>
    <NAlert v-if="historicalReadOnly" type="warning" title="历史演示记录 · 只读" :show-icon="true">内容均为历史模拟记录，保留原始标记。此记录不能继续发送消息、执行任务或生成摘要；当前对话使用独立上下文。</NAlert>

    <NAlert v-if="error" type="error" role="alert">{{ error }} <NButton v-if="!conversation&&!busy" @click="reopen">重新打开对话</NButton><NButton @click="emit('editSettings')">检查员工配置</NButton></NAlert><NAlert v-if="notice" type="info" role="status">{{ notice }}</NAlert>

      <div v-if="embedded&&!conversation" class="empty-conversation-toolbar conversation-toolbar"><NButton text aria-label="返回对话列表" :disabled="busy||interrupting" @click="emit('close')">← 返回对话列表</NButton></div>
      <NSkeleton v-if="busy && !conversation" height="200px" :sharp="false" />
      <NEmpty v-else-if="loaded && !conversation" description="暂时无法打开对话，请核对使用权限和模型配置。" />
      <div v-if="conversation" class="chat-task-grid" :class="{'show-desktop-tasks':taskView&&!narrow}">
        <NCard class="chat-panel" :bordered="true" content-style="padding: 0;">
          <div class="conversation-toolbar"><div class="conversation-title"><NButton v-if="embedded" text aria-label="返回对话列表" :disabled="busy||interrupting" @click="emit('close')">← 返回</NButton><EmployeeAvatar :name="entity.name" :preset="entity.avatarPreset" :identity-key="entity.id" size="conversation"/><h2>{{entity.name}} <span class="chat-ai">AI</span></h2><InfoHint label="会话与后台任务说明"><p>切换员工或工作区不会取消回复和后台任务。需要取消任务时，请在任务详情中操作。</p><p class="field-note">会话 {{conversation.id}}</p></InfoHint></div><div class="conversation-actions"><NButton class="refresh-messages" size="small" aria-label="刷新消息" :disabled="busy||interrupting" @click="refresh"><svg class="refresh-symbol" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M16 6A7 7 0 1 0 17 11M16 2v5h-5"/></svg><span>刷新消息</span></NButton><NButton v-if="!historicalReadOnly" id="conversation-task-toggle" size="small" :aria-expanded="taskView" @click="taskView=!taskView">{{taskView?'收起任务':'查看本会话任务'}}</NButton></div></div>
          <div class="chat-messages" role="log" aria-live="polite" aria-label="会话消息"><article v-for="message in messages" :key="message.id" class="chat-message" :class="{ 'from-user': message.role === 'user', simulated: message.simulated }"><small>{{message.source==='task_delivery'?'任务反馈':message.role==='user'?'我':message.role==='assistant'?entity.name:'系统'}}{{ message.simulated || historicalReadOnly ? ' · 演示 / 模拟' : '' }}</small><div class="message-bubble"><p>{{ message.text }}</p></div></article><NEmpty v-if="!messages.length" :description="historicalReadOnly ? '此历史演示记录没有消息。' : '发送消息开始协作。'" /><div v-if="generating" class="reply-status" role="status"><span class="typing-indicator">•••</span>正在回复…</div></div>
          <NAlert v-if="!continuationAllowed&&!historicalReadOnly" type="warning" role="status">{{readOnlyReason}} 你仍可查看此对话的历史消息。</NAlert><NAlert v-if="entity.enabled === false" type="warning">员工已停用，仅可查看历史；恢复后才能发送新消息。</NAlert><div v-if="!historicalReadOnly && entity.enabled !== false&&continuationAllowed" class="composer"><NAlert v-if="turn?.status === 'failed'" type="error">本轮回复失败。请核对配置和已有任务状态。</NAlert><NAlert v-if="turn?.status === 'canceled'" type="info">本轮回复已中断，不代表业务任务取消。</NAlert><form @submit.prevent="send"><label class="composer-label"><span class="sr-only">消息</span><NInput v-model:value="text" :input-props="{ 'aria-label': '消息', onKeydown:onComposerKey, onCompositionstart:()=>composing=true, onCompositionend:()=>composing=false }" type="textarea" :disabled="busy" :maxlength="8000" :autosize="{ minRows: 1, maxRows: 6 }" :placeholder="`给${entity.name}交代工作…`" /></label><div class="composer-actions"><InfoHint label="消息输入方式">Enter 发送，Option+Enter 换行。最多 8000 字，当前 {{text.length}} 字。</InfoHint><NButton v-if="generating" :loading="interrupting" :disabled="interrupting" @click="interrupt">申请中断回复</NButton><NButton class="send-message" aria-label="发送消息" :disabled="busy || !text.trim()" :loading="busy" attr-type="submit" type="primary">发送</NButton></div></form></div>
        </NCard>
        <aside v-if="!historicalReadOnly&&taskView&&!narrow" class="session-tasks" aria-label="本会话任务"><ConversationTaskList @updated="refresh" :key="conversation.id" :base="base" :conversation-id="conversation.id" @session-expired="emit('sessionExpired')"/></aside>
        <NCard v-if="historicalReadOnly" class="historical-task-note" title="历史模拟记录"><p>此记录仅供查看，不提供任务操作。请返回当前员工对话继续工作。</p></NCard>
      </div>

    <NDrawer v-if="narrow&&conversation&&!historicalReadOnly" :show="taskView" :width="'min(100vw, 26rem)'" placement="right" :auto-focus="true" @update:show="v=>taskView=v"><NDrawerContent title="本会话任务" closable><ConversationTaskList embedded v-if="taskView" :base="base" :conversation-id="conversation.id" @session-expired="emit('sessionExpired')"/></NDrawerContent></NDrawer>

  </section>
</template>
<style scoped>
.entity-workspace{min-width:0;display:grid;gap:1rem}.chat-header-leading,.conversation-title,.conversation-actions{display:flex;align-items:center;gap:.5rem;min-width:0}.workspace-heading{margin-bottom:0}.conversation-toolbar{display:flex;align-items:center;justify-content:space-between;gap:.75rem;padding:.75rem 1rem;border-bottom:1px solid var(--subtle);flex-wrap:wrap}.conversation-title h2{font-size:1rem;line-height:1.5;margin:0}.conversation-actions{flex-wrap:wrap;margin-left:auto}.refresh-symbol{display:none;width:1rem;height:1rem}.chat-task-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:1rem;align-items:start}.chat-task-grid.show-desktop-tasks{grid-template-columns:minmax(0,1fr) minmax(18rem,23rem)}.session-tasks{min-width:0}.chat-panel{min-width:0;overflow:hidden}.chat-messages{min-height:18rem;height:clamp(18rem,calc(100dvh - 29rem),38rem);overflow:auto;padding:1.25rem;display:flex;flex-direction:column;gap:1rem;background:var(--surface)}.chat-message{display:flex;flex-direction:column;align-items:flex-start;max-width:85%;padding:0;background:transparent;border:0}.chat-message small{font-size:.75rem;color:var(--muted);margin-bottom:.375rem}.message-bubble{border-radius:.25rem .75rem .75rem;border:1px solid var(--subtle);background:var(--background);padding:.625rem .875rem}.message-bubble p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.chat-message.from-user{margin-left:auto;align-items:flex-end}.from-user .message-bubble{border-radius:.75rem .25rem .75rem .75rem;background:var(--tint);border-color:var(--subtle);color:var(--text)}.composer{padding:.75rem 1rem max(.75rem,env(safe-area-inset-bottom));border-top:1px solid var(--subtle)}.composer form{display:flex;align-items:flex-end;gap:.5rem}.composer-label{flex:1;min-width:0}.composer-actions{display:flex;align-items:center;gap:.5rem}.composer-actions .info-hint{flex:none}.reply-status{font-size:.875rem;color:var(--muted)}.typing-indicator{font-size:1.25rem;letter-spacing:.1875rem;color:var(--brand);margin-right:.5rem}.historical-task-note{color:var(--muted)}
@media(max-width:68.75rem){.chat-task-grid.show-desktop-tasks{grid-template-columns:minmax(0,1fr) minmax(16rem,20rem)}}
@media(max-width:47.5rem){.conversation-toolbar{padding:.5rem .75rem;gap:.25rem;flex-wrap:nowrap}.conversation-title{gap:0}.conversation-title h2{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.conversation-actions{gap:.25rem;flex-wrap:nowrap}.refresh-messages span{display:none}.refresh-symbol{display:block}.conversation-actions :deep(.n-button){font-size:.875rem;padding-inline:.5rem}.chat-messages{min-height:14rem;height:clamp(14rem,40dvh,30rem);padding:1rem}.chat-message{max-width:94%}.composer{padding:.5rem .75rem max(.5rem,env(safe-area-inset-bottom))}.composer-actions{gap:.25rem}}
</style>

<style scoped>
.chat-task-grid.show-desktop-tasks{grid-template-columns:minmax(0,1fr) 280px;gap:0;border:1px solid var(--subtle);border-radius:12px;overflow:hidden;background:var(--surface)}.chat-task-grid .chat-panel{border:0;border-radius:0}.session-tasks{border-left:1px solid var(--subtle);height:100%;background:var(--surface)}.chat-ai{font-size:11px;background:var(--tint);color:var(--selectedText);padding:2px 4px;border-radius:3px}.chat-messages{background:var(--background);padding:24px 32px;height:clamp(320px,calc(100dvh - 370px),650px)}.message-bubble{background:var(--surface);border-radius:4px 12px 12px}.from-user .message-bubble{background:var(--brand);color:var(--onPrimary);border-color:transparent}.composer{background:var(--background);border-top:0;padding:16px 24px}.composer form{background:var(--surface);padding:12px;border:1px solid var(--border);border-radius:12px;box-shadow:0 2px 4px #00000008}.composer :deep(.n-input){--n-border:0!important;--n-border-hover:0!important;--n-border-focus:0!important;--n-box-shadow-focus:none!important;background:transparent}.composer :deep(.n-input__border),.composer :deep(.n-input__state-border){border:0!important}.message-bubble p{font-size:15px;line-height:24px}@media(max-width:1100px){.chat-task-grid.show-desktop-tasks{grid-template-columns:minmax(0,1fr) 240px}.chat-messages{padding:20px}}@media(max-width:760px){.chat-messages{padding:16px}.composer{padding:12px}.conversation-title :deep(.employee-avatar){display:none}.chat-task-grid{border-radius:12px}}
</style>
